import * as DB from './db.js';
import {esc,icon,btn,iconBtn,thumb,field,selectField,checkField,empty,toast,showDialog,closeDialog,safeError,download,compressImage,loadScript} from './ui.js';
import {openScanner,closeScanner} from './scanner.js';
import {csvExport,previewCSV,importCSV,validateBackup,restoreBackup,makeBackup} from './transfer.js';
import {seedDemo} from './demo.js';
const $=s=>document.querySelector(s);
let data={},settings={...DB.defaults},cart=DB.newCart(),demo=localStorage.getItem('storeflow-demo')==='1',route='dashboard',filters={},limit=40,busy=false,range='7',customFrom='',customTo='',importRows=[],pendingBackup=null,productAfterSave=null,installEvent=null,draftTimer;
let channel;try{channel=new BroadcastChannel('storeflow:'+new URL('../../',import.meta.url).pathname);}catch{}
const money=(v=0)=>`${esc(settings.symbol)} ${Number(v/100).toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:2})}`;
const fmtDate=(s,withTime=false)=>new Date(s).toLocaleString(undefined,withTime?{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'}:{month:'short',day:'numeric'});
const products=()=>data.products.filter(p=>!p.deleted);
const product=id=>data.products.find(p=>p.id===id);
const lowProducts=()=>products().filter(p=>p.active&&p.stock<=p.minStock);
const currentTotals=()=>{try{return DB.totals(cart,data.products);}catch{return {subtotal:0,discount:0,tax:0,charges:0,total:0,cost:0,profit:0,lines:[]};}};
const nameOf=(store,id)=>data[store].find(x=>x.id===id)?.name||'Walk-in customer';
const searchProduct=(p,q)=>[p.name,p.sku,p.barcode,p.category,p.brand].join(' ').toLowerCase().includes(q.toLowerCase());
const profitPct=p=>p.price?((p.price-p.cost)/p.price*100).toFixed(1):'0.0';
const status=p=>!p.active?['Inactive','neutral']:p.expiry&&p.expiry<DB.today()?['Expired','danger']:p.stock<=0?['Out of stock','danger']:p.stock<=p.minStock?['Low stock','warning']:['In stock',''];
const badge=p=>{const [text,cls]=status(p);return `<span class="badge ${cls}">${text}</span>`;};
const heading=(title,sub,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const metric=(label,value,ico,note,featured=false)=>`<div class="metric ${featured?'featured':''}"><div class="metric-top">${label}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;
const searchInput=(placeholder,value='',id='page-search')=>`<div class="search-input">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(value)}" autocomplete="off"></div>`;
const table=(headers,rows,emptyText='No records to show.')=>rows.length?`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('Nothing here yet',emptyText);
const listFooter=(count)=>`<div class="panel-footer"><span>Showing ${Math.min(limit,count)} of ${count}</span>${count>limit?btn('Show more','more-records','down','compact'):''}</div>`;
function rangeDates(){const end=new Date();end.setHours(23,59,59,999);const start=new Date();start.setHours(0,0,0,0);if(range==='yesterday'){start.setDate(start.getDate()-1);end.setDate(end.getDate()-1);}else if(range==='month')start.setDate(1);else if(range==='custom'){return [new Date(customFrom+'T00:00:00').getTime(),new Date(customTo+'T23:59:59.999').getTime()];}else if(range!=='today')start.setDate(start.getDate()-(Number(range)-1));return [+start,+end];}
function inRange(date,a,b){const d=+new Date(date);return d>=a&&d<=b;}
function stats(a,b){const sales=data.sales.filter(s=>inRange(s.date,a,b)),returns=data.returns.filter(r=>inRange(r.date,a,b));return {sales,returns,revenue:sales.reduce((n,s)=>n+s.total,0)-returns.reduce((n,r)=>n+r.amount,0),net:sales.reduce((n,s)=>n+s.subtotal-s.discount+s.charges,0)-returns.reduce((n,r)=>n+r.net,0),cost:sales.reduce((n,s)=>n+s.cost,0)-returns.reduce((n,r)=>n+r.cost,0),profit:sales.reduce((n,s)=>n+s.profit,0)-returns.reduce((n,r)=>n+r.profit,0),units:DB.roundQty(sales.reduce((n,s)=>n+s.lines.reduce((x,l)=>x+l.qty,0),0)-returns.reduce((n,r)=>n+r.items.reduce((x,l)=>x+l.qty,0),0))};}
function rankings(st){const m=new Map();for(const s of st.sales)for(const l of s.lines){const v=m.get(l.productId)||{id:l.productId,name:l.name,qty:0,revenue:0,profit:0};v.qty+=l.qty;v.revenue+=l.total;v.profit+=l.profit;m.set(l.productId,v);}for(const r of st.returns)for(const l of r.items){const v=m.get(l.productId)||{id:l.productId,name:l.name,qty:0,revenue:0,profit:0};v.qty-=l.qty;v.revenue-=l.amount;v.profit-=l.profit;m.set(l.productId,v);}return [...m.values()].sort((a,b)=>b.qty-a.qty);}
function dateControl(){return `<select id="range" class="date-filter" aria-label="Report date range">${[['today','Today'],['yesterday','Yesterday'],['7','Last 7 days'],['30','Last 30 days'],['month','This month'],['custom','Custom range']].map(([v,l])=>`<option value="${v}" ${range===v?'selected':''}>${l}</option>`).join('')}</select>`;}
function customRange(){return range==='custom'?`<div class="toolbar date-custom"><label for="date-from">From</label><input type="date" id="date-from" value="${customFrom}"><label for="date-to">To</label><input type="date" id="date-to" value="${customTo}"></div>`:'';}
function lineChart(a,b){
 let n=Math.min(30,Math.max(1,Math.ceil((b-a)/86400000))),points=[];
 for(let i=0;i<n;i++){const from=a+(b-a+1)*i/n,to=a+(b-a+1)*(i+1)/n;const s=stats(from,to-(i<n-1?1:0));points.push({s,date:from});}
 const all=points.flatMap(p=>[p.s.revenue,p.s.profit]),max=Math.max(100,...all),min=Math.min(0,...all),span=max-min||1;
 const x=i=>54+i*596/Math.max(1,n-1),y=v=>180-(v-min)/span*145;
 const path=key=>points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.s[key]).toFixed(1)}`).join(' ');
 const labels=[0,1,2,3].map(i=>{const v=min+span*i/3;return `<line x1="54" y1="${y(v)}" x2="650" y2="${y(v)}" class="chart-grid"/><text x="42" y="${y(v)+4}" text-anchor="end">${v>=100000?(v/100000).toFixed(1)+'k':Math.round(v/100)}</text>`;}).join('');
 const ticks=[...new Set([0,Math.floor((n-1)/3),Math.floor(2*(n-1)/3),n-1])].map(i=>`<text x="${x(i)}" y="208" text-anchor="middle">${fmtDate(points[i].date)}</text>`).join('');
 return `<svg class="chart" viewBox="0 0 680 220" role="img" aria-label="Sales and profit chart in ${esc(settings.currency)} for the selected period"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3a8d6b" stop-opacity=".17"/><stop offset="100%" stop-color="#3a8d6b" stop-opacity="0"/></linearGradient></defs>${labels}<path d="${path('revenue')} L${x(n-1)},${y(0)} L54,${y(0)}Z" fill="url(#area)"/><path d="${path('revenue')}" fill="none" stroke="#3a8d6b" stroke-width="2.7" stroke-linejoin="round"/><path d="${path('profit')}" fill="none" stroke="#a1bc66" stroke-width="2.2" stroke-linejoin="round"/>${ticks}</svg>`;
}
function salesRows(sales){return sales.map(s=>`<tr><td><button class="table-link" data-action="receipt" data-id="${s.id}"><strong>${esc(s.invoice)}</strong></button><div class="small muted">${fmtDate(s.date,true)}</div></td><td>${esc(s.customerName)}</td><td>${DB.roundQty(s.lines.reduce((n,l)=>n+l.qty,0))} items</td><td><span class="badge neutral">${esc(s.payment.method)}</span></td><td><strong>${money(s.total-s.refunded)}</strong>${s.refunded?'<div class="small muted">After refund</div>':''}</td><td>${iconBtn('View invoice','receipt','chevron',`data-id="${s.id}"`)}</td></tr>`);}
function shell(){
 const nav=[['dashboard','Overview','grid'],['pos','Point of sale','cart'],['products','Products','box'],['inventory','Inventory','stock'],['stock-in','Stock in','plus'],['sales','Sales & returns','receipt'],['customers','Customers','users'],['reports','Reports','chart'],['categories','Categories & brands','tag']];
 $('#sidebar').innerHTML=`<a class="brand" href="#dashboard"><span class="brand-icon">${icon('store')}</span><span class="brand-text">Store<em>Flow</em><span style="font-size:10px;letter-spacing:1.5px;display:block;font-weight:550;color:var(--muted)">POINT OF SALE</span></span></a><div class="nav-section">WORKSPACE</div><nav>${nav.map(([r,l,i])=>`<a class="nav-link ${route===r?'active':''}" title="${l}" href="#${r}">${icon(i)}<span>${l}</span>${r==='inventory'&&lowProducts().length?`<span class="nav-count">${lowProducts().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#settings" title="Settings" class="nav-link ${route==='settings'?'active':''}">${icon('settings')}<span>Settings</span></a><div class="local-card"><strong>${icon('shield')} Local & private</strong><p>Your business data stays on this device. Keep a regular backup.</p></div></div>`;
 const title=nav.find(x=>x[0]===route)?.[1]||({movements:'Stock movements',settings:'Settings',more:'Your workspace'}[route]||'Overview');
 $('#topbar').innerHTML=`${iconBtn('Collapse sidebar','collapse','menu','class="collapse-btn"')}<span class="breadcrumb">${title}</span><button class="top-search" data-action="global-search" aria-label="Search products, customers, invoices">${icon('search')}<span>Search your store…</span><kbd>/</kbd></button><div class="top-right">${iconBtn('Toggle theme','theme','moon')}<a href="#settings" class="shop-label"><strong>${esc(settings.name)}</strong><span>${demo?'Demo workspace':'Store owner'}</span></a><a href="#settings" class="avatar" aria-label="Store settings">${esc(settings.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</a></div>`;
 $('#topbar').firstElementChild.classList.add('collapse-btn');$('#topbar .top-right button').classList.add('theme-toggle');
 $('#mobile-nav').innerHTML=[['dashboard','Home','grid'],['pos','POS','cart'],['scan','Scan','scan'],['inventory','Stock','box'],['more','More','menu']].map(([r,l,i])=>r==='scan'?`<button class="scan-nav" data-action="scan-sell"><span>${icon(i)}</span>${l}</button>`:`<a href="#${r}" class="${route===r?'active':''}">${icon(i)}${l}</a>`).join('');
 $('#demo-banner').innerHTML=demo?`<div class="demo-banner"><span><strong>Demo workspace.</strong> Explore freely. Your real shop stays separate.</span>${btn('Exit demo','demo-exit','logout','ghost')}</div>`:'';
 document.body.classList.toggle('dark',(localStorage.getItem('storeflow-theme')||settings.theme)==='dark');
 document.body.classList.toggle('collapsed',localStorage.getItem('storeflow-collapsed')==='1');
 $('#connection').textContent=navigator.onLine?'Saved on this device':'Offline · saved on this device';document.title=`${title} · StoreFlow POS`;
}
function dashboard(){
 const dayStart=new Date();dayStart.setHours(0,0,0,0);const stToday=stats(+dayStart,Date.now()),[a,b]=rangeDates(),st=stats(a,b),ranks=rankings(st),recent=[...data.sales].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 const hour=new Date().getHours(),greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';
 return heading(`${greeting}${settings.owner?', '+esc(settings.owner.split(' ')[0]):''} <span style="font-weight:400">☀</span>`,`Here’s what’s happening at ${esc(settings.name)}.`,dateControl()+btn('New sale','new-sale','plus','primary'))+customRange()+`<div class="metrics">${metric("Today's sales",money(stToday.revenue),'wallet',`${stToday.sales.length} completed orders`,true)}${metric("Today's profit",money(stToday.profit),'trend',`${stToday.net?Math.round(stToday.profit/stToday.net*100):0}% estimated net margin`)}${metric("Today's orders",stToday.sales.length,'receipt',`${stToday.units} products sold today`)}${metric('Low stock',lowProducts().length,'alert',`<a href="#inventory" data-action="low-stock">${products().filter(p=>p.active&&p.stock<=0).length} out of stock · View inventory →</a>`)}</div>
 <div class="quick-actions">${[['new-sale','cart','New sale','Open the cashier'],['scan-sell','scan','Scan product','Point. Scan. Sell.'],['add-product','plus','Add product','Grow your inventory'],['stock-in','stock','Receive stock','Keep shelves ready']].map(([a,i,l,s])=>`<button class="quick-action" data-action="${a}"><span>${icon(i)}</span><div>${l}<small>${s}</small></div></button>`).join('')}</div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Sales overview</h2><p>A clear view of your store’s performance</p></div><div class="chart-legend"><span><i></i>Sales</span><span class="profit"><i></i>Profit</span></div></div><div class="chart-summary"><div><span class="chart-total">${money(st.revenue)}</span><div class="muted">Net sales for this period</div></div><span class="badge">${st.sales.length} orders</span></div><div class="panel-body" style="padding-top:18px;padding-bottom:8px">${lineChart(a,b)}</div></section>
 <section class="panel"><div class="panel-head"><div><h2>Top products</h2><p>Your customers’ favorites</p></div><a class="text-button" href="#reports">View all</a></div><div class="panel-body">${ranks.length?`<ol class="rank-list">${ranks.slice(0,4).map((r,i)=>`<li class="rank-row"><span class="rank-number">${i+1}</span>${thumb(product(r.id)||r)}<div><div class="rank-name">${esc(r.name)}</div><div class="rank-meta">${DB.roundQty(r.qty)} units sold</div></div><div class="rank-price">${money(r.revenue)}</div></li>`).join('')}</ol>`:empty('Your bestsellers go here','Complete your first sale to see which products your customers love.','','chart')}</div></section></div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Recent sales</h2><p>The latest from your counter</p></div><a href="#sales" class="text-button">View all ${icon('arrow')}</a></div>${table(['Invoice','Customer','Items','Payment','Amount',''],salesRows(recent),'Your first completed sale will appear here.')}</section><section class="panel"><div class="panel-head"><div><h2>Stock needs attention</h2><p>A little restock goes a long way</p></div><span class="badge warning">${lowProducts().length} products</span></div><div class="panel-body">${lowProducts().length?lowProducts().slice(0,4).map(p=>`<div class="low-stock-item">${thumb(p)}<div><button class="table-link" data-action="stock-form" data-id="${p.id}"><strong>${esc(p.name)}</strong></button><small>Minimum ${p.minStock} ${esc(p.unit)}</small></div><span class="badge ${p.stock<=0?'danger':'warning'}">${p.stock} left</span></div>`).join(''):empty('Shelves are looking good','Low-stock products will appear here.','','check')}</div></section></div>`;
}
function productFilters(){return `<div class="toolbar">${searchInput('Search name, barcode, SKU or brand…',filters.q||'')}<select id="category-filter" aria-label="Filter by category"><option value="">All categories</option>${[...new Set(products().map(p=>p.category))].sort().map(c=>`<option ${filters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="brand-filter" aria-label="Filter by brand"><option value="">All brands</option>${[...new Set(products().map(p=>p.brand).filter(Boolean))].sort().map(c=>`<option ${filters.brand===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="status-filter" aria-label="Stock status">${['All statuses','In stock','Low stock','Out of stock','Expired','Inactive'].map((c,i)=>`<option value="${i?c:''}" ${filters.status===(i?c:'')?'selected':''}>${c}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort products">${[['name','Name A–Z'],['stock','Stock: low first'],['price','Price: low first'],['profit','Profit: high first'],['category','Category'],['recent','Recently added']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function filteredProducts(){let ps=products().filter(p=>(!filters.q||searchProduct(p,filters.q))&&(!filters.category||p.category===filters.category)&&(!filters.brand||p.brand===filters.brand)&&(!filters.status||(filters.status==='Low stock'?p.active&&p.stock<=p.minStock:status(p)[0]===filters.status)));return ps.sort((a,b)=>filters.sort==='stock'?a.stock-b.stock:filters.sort==='price'?a.price-b.price:filters.sort==='profit'?(b.price-b.cost)-(a.price-a.cost):filters.sort==='recent'?b.created.localeCompare(a.created):filters.sort==='category'?a.category.localeCompare(b.category):a.name.localeCompare(b.name));}
function inventory(isInventory=false){
 const ps=filteredProducts(),all=products(),cost=all.reduce((n,p)=>n+Math.round(p.cost*p.stock),0),value=all.reduce((n,p)=>n+Math.round(p.price*p.stock),0);
 return heading(isInventory?'Inventory':'Products',isInventory?'Know what you have. Keep your bestsellers in stock.':'Everything on your shelves, in one place.',btn('Lookup','scan-lookup','scan')+btn('Import CSV','csv-import','upload')+btn('Add product','add-product','plus','primary'))+
 (isInventory?`<div class="metrics">${metric('Inventory value',money(cost),'box',`${all.length} products at purchase cost`,true)}${metric('Total stock units',DB.roundQty(all.reduce((n,p)=>n+p.stock,0)),'stock',`${all.filter(p=>p.stock<=0).length} products out of stock`)}${metric('Selling value',money(value),'wallet','Estimated at current prices')}${metric('Potential profit',money(value-cost),'trend',`${all.filter(p=>p.expiry&&p.expiry<DB.today()).length} expired products`)}</div><div class="page-subnav"><a class="active" href="#inventory">Stock overview</a><a href="#movements">Stock movements</a><a href="#stock-in">Receive stock</a></div>`:'')+
 productFilters()+`<div class="panel">${ps.length?table(['Product','Category','Purchase','Selling','Stock','Status','Actions'],ps.slice(0,limit).map(p=>`<tr><td><button class="table-link product-cell" data-action="product-detail" data-id="${p.id}">${thumb(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.barcode||'No barcode')}</small></span></button></td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td>${money(p.price)}<div class="small muted">${profitPct(p)}% margin</div></td><td><strong>${p.stock}</strong> <span class="muted small">${esc(p.unit)}</span><div class="small muted">Min. ${p.minStock}</div></td><td>${badge(p)}</td><td><div class="actions">${iconBtn('Edit product','edit-product','edit',`data-id="${p.id}"`)}${iconBtn('Adjust stock','adjust-stock','stock',`data-id="${p.id}"`)}</div></td></tr>`)):empty('No products yet',all.length?'No products match these filters.':'Scan your first product or add one manually.',btn('Scan product','scan-add-mode','scan')+btn('Add product','add-product','plus','primary'))}${listFooter(ps.length)}</div><div class="actions" style="margin-top:18px">${btn('Export products','export-products','download')}${btn('Print barcode labels','labels','barcode')}</div>`;
}
function pos(){
 const ps=products().filter(p=>p.active&&(!filters.q||searchProduct(p,filters.q))&&(!filters.category||p.category===filters.category));
 return heading('Point of sale','A smooth checkout starts here.',btn(`Held bills${data.heldBills.length?' ('+data.heldBills.length+')':''}`,'held-bills','hold')+btn('Fast sell','fast-sell','light')+btn('Scan items','scan-sell','scan','primary'))+`<div class="pos-layout"><section><div class="toolbar">${searchInput('Search products or enter a barcode…',filters.q||'')}</div><div class="chips"><button class="chip ${!filters.category?'active':''}" data-action="pos-category" data-category="">All products</button>${[...new Set(products().map(p=>p.category))].map(c=>`<button class="chip ${filters.category===c?'active':''}" data-action="pos-category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="pos-products">${ps.slice(0,limit).map(p=>`<button class="product-card" data-action="cart-add" data-id="${p.id}">${thumb(p)}<small>${esc(p.category)}</small><strong>${esc(p.name)}</strong><small>${p.stock} ${esc(p.unit)} available</small><div class="product-card-bottom">${money(p.price)}<span>${icon('plus')}</span></div></button>`).join('')}</div>${!ps.length?empty('Ready for your first product','Add products to start scanning and selling.',btn('Add product','add-product','plus','primary')):''}${ps.length>limit?listFooter(ps.length):''}</section><section class="panel cart" id="cart-panel">${cartMarkup()}</section></div>`;
}
function cartMarkup(){const t=currentTotals();return `<div class="cart-head"><h2>Current bill <span class="badge neutral">${cart.lines.length}</span></h2>${btn('Clear','cart-clear','','ghost compact')}</div><div class="cart-lines">${cart.lines.length?cart.lines.map(l=>{const p=product(l.productId);return `<div class="cart-line"><div class="cart-line-top"><strong>${esc(p?.name||'Unavailable product')}</strong><button class="table-link" aria-label="Remove ${esc(p?.name||'product')}" data-action="cart-remove" data-id="${l.productId}">${icon('close')}</button></div><div class="cart-line-bottom"><span>${money(p?.price||0)} / ${esc(p?.unit||'pcs')}</span><div class="qty-control"><button aria-label="Decrease quantity" data-action="cart-minus" data-id="${l.productId}">−</button><input aria-label="Quantity for ${esc(p?.name)}" class="cart-qty" data-id="${l.productId}" type="number" min="0.001" step="0.001" value="${l.qty}"><button aria-label="Increase quantity" data-action="cart-plus" data-id="${l.productId}">+</button></div><strong>${money(Math.round((p?.price||0)*l.qty))}</strong></div></div>`;}).join(''):`<div class="cart-empty">${icon('cart')}<p style="margin:12px 0 0">Your bill is ready for its first item.</p><small>Tap a product or scan a barcode.</small></div>`}</div><div class="cart-settings"><div class="field"><label for="cart-customer">Customer <span class="muted">(optional)</span></label><select id="cart-customer"><option value="">Walk-in customer</option>${data.customers.map(c=>`<option value="${c.id}" ${cart.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><details><summary class="small">Discount, tax & charges</summary><div class="form-grid" style="margin-top:12px"><div><label for="cart-discount">Discount</label><input type="number" id="cart-discount" min="0" step=".01" value="${cart.discountType==='percent'?cart.discount:cart.discount/100}"></div><div><label for="cart-discountType">Discount type</label><select id="cart-discountType"><option value="fixed" ${cart.discountType==='fixed'?'selected':''}>Fixed amount</option><option value="percent" ${cart.discountType==='percent'?'selected':''}>Percent</option></select></div><div><label for="cart-tax">Tax %</label><input type="number" id="cart-tax" min="0" max="100" step=".01" value="${cart.tax}"></div><div><label for="cart-charges">Charges</label><input type="number" id="cart-charges" min="0" step=".01" value="${cart.charges/100}"></div></div></details></div><div class="cart-summary"><div class="summary-row"><span class="muted">Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-row"><span class="muted">Discount</span><span>− ${money(t.discount)}</span></div>`:''}${t.tax?`<div class="summary-row"><span class="muted">Tax (${cart.tax}%)</span><span>${money(t.tax)}</span></div>`:''}${t.charges?`<div class="summary-row"><span class="muted">Additional charges</span><span>${money(t.charges)}</span></div>`:''}<div class="summary-row total"><span>Total</span><span>${money(t.total)}</span></div><div class="actions">${btn('Hold bill','hold-bill','hold')}${btn('Checkout','checkout','arrow','primary',cart.lines.length?'style="flex:1"':'disabled style="flex:1"')}</div><p class="muted small" style="text-align:center;margin:13px 0 0">Stock updates when you complete the sale.</p></div>`;}
function stockIn(){return heading('Receive stock','Restock the shelf and keep a record of every delivery.',btn('Scan product','scan-stock','scan','primary'))+`<div class="page-subnav"><a href="#inventory">Stock overview</a><a href="#movements">Stock movements</a><a class="active" href="#stock-in">Receive stock</a></div><div class="toolbar">${searchInput('Find a product to receive…',filters.q||'')}</div><div class="panel">${table(['Product','Current stock','Purchase price','Selling price',''],filteredProducts().slice(0,limit).map(p=>`<tr><td><div class="product-cell">${thumb(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.barcode||p.sku||'No barcode')}</small></span></div></td><td>${p.stock} ${esc(p.unit)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${btn('Receive stock','stock-form','plus','',`data-id="${p.id}"`)}</td></tr>`),'Add a product or scan an unknown barcode to create one.')}${listFooter(filteredProducts().length)}</div>`;}
function movements(){const rows=[...data.movements].filter(m=>(!filters.q||[m.product,m.reason,m.reference,m.type].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.type||m.type===filters.type)).sort((a,b)=>b.date.localeCompare(a.date));return heading('Stock movements','Every change, with a reason and a reference.',btn('Export CSV','export-movements','download'))+`<div class="page-subnav"><a href="#inventory">Stock overview</a><a class="active" href="#movements">Stock movements</a><a href="#stock-in">Receive stock</a></div><div class="toolbar">${searchInput('Search product, reason or reference…',filters.q||'')}<select id="movement-filter" aria-label="Movement type"><option value="">All types</option>${['Opening Stock','Stock In','Sale','Return','Damaged','Adjustment','Import'].map(v=>`<option ${filters.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="panel">${table(['Date','Product','Type','Before','Change','After','Reason / reference'],rows.slice(0,limit).map(m=>`<tr><td>${fmtDate(m.date,true)}</td><td>${esc(m.product)}</td><td><span class="badge neutral">${esc(m.type)}</span></td><td>${m.before}</td><td style="color:${m.change<0?'var(--red)':'var(--green)'}">${m.change>0?'+':''}${m.change}</td><td><strong>${m.after}</strong></td><td>${esc(m.reason)}<div class="small muted">${esc(m.reference)}</div></td></tr>`))}${listFooter(rows.length)}</div>`;}
function sales(){const rows=[...data.sales].filter(s=>(!filters.q||[s.invoice,s.customerName].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.payment||s.payment.method===filters.payment)&&(!filters.from||s.date>=new Date(filters.from+'T00:00:00').toISOString())&&(!filters.to||s.date<=new Date(filters.to+'T23:59:59.999').toISOString())).sort((a,b)=>b.date.localeCompare(a.date));return heading('Sales & returns','Every bill, every payment, every return.',btn('Export sales','export-sales','download')+btn('New sale','new-sale','plus','primary'))+`<div class="toolbar">${searchInput('Search invoice or customer…',filters.q||'')}<select id="payment-filter" aria-label="Payment method"><option value="">All payments</option>${['Cash','Card','Bank Transfer','Other'].map(v=>`<option ${filters.payment===v?'selected':''}>${v}</option>`).join('')}</select><input type="date" id="sales-from" aria-label="Sales from date" value="${filters.from||''}" style="width:auto"><input type="date" id="sales-to" aria-label="Sales to date" value="${filters.to||''}" style="width:auto"></div><div class="panel">${table(['Invoice','Customer','Items','Payment','Net amount',''],salesRows(rows.slice(0,limit)),'Completed sales will appear here. Open an invoice to print or return items.')}${listFooter(rows.length)}</div>`;}
function customers(){const rows=data.customers.filter(c=>!filters.q||[c.name,c.phone,c.email].join(' ').toLowerCase().includes(filters.q.toLowerCase()));return heading('Customers','Familiar faces. Better relationships.',btn('Export CSV','export-customers','download')+btn('Add customer','add-customer','plus','primary'))+`<div class="toolbar">${searchInput('Search name, phone or email…',filters.q||'')}</div><div class="panel">${table(['Customer','Contact','Orders','Net spending','Last purchase',''],rows.slice(0,limit).map(c=>{const ss=data.sales.filter(s=>s.customerId===c.id).sort((a,b)=>b.date.localeCompare(a.date));return `<tr><td><div class="product-cell">${thumb(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.address)}</small></span></div></td><td>${esc(c.phone||'—')}<div class="muted small">${esc(c.email)}</div></td><td>${ss.length}</td><td>${money(ss.reduce((n,s)=>n+s.total-s.refunded,0))}</td><td>${ss.length?fmtDate(ss[0].date):'—'}</td><td>${iconBtn('Edit customer','edit-customer','edit',`data-id="${c.id}"`)}</td></tr>`;}),'Add customers to track purchase history and spending.')}${listFooter(rows.length)}</div>`;}
function bars(map){const arr=[...map.entries()].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...arr.map(x=>Math.abs(x[1])));return arr.length?`<div class="bars">${arr.map(([name,v])=>`<div><div class="bar-label"><span>${esc(name)}</span><strong>${money(v)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(v)/max*100}%"></div></div></div>`).join('')}</div>`:empty('No sales in this period','Choose another date range or complete your first sale.','','chart');}
function reports(){const [a,b]=rangeDates(),st=stats(a,b),ranks=rankings(st),categories=new Map(),payments=new Map();for(const s of st.sales){payments.set(s.payment.method,(payments.get(s.payment.method)||0)+s.total);for(const l of s.lines)categories.set(l.category,(categories.get(l.category)||0)+l.total);}for(const r of st.returns){payments.set(r.payment,(payments.get(r.payment)||0)-r.amount);for(const l of r.items)categories.set(l.category,(categories.get(l.category)||0)-l.amount);}return heading('Reports','Turn everyday sales into a clearer picture.',dateControl()+btn('Export sales','export-sales','download'))+customRange()+`<div class="metrics">${metric('Net sales',money(st.revenue),'wallet','Includes tax · less refunds',true)}${metric('Estimated profit',money(st.profit),'trend',`${st.net?(st.profit/st.net*100).toFixed(1):'0'}% margin · tax excluded`)}${metric('Cost of goods',money(st.cost),'box','Purchase cost saved at sale time')}${metric('Average bill',money(st.sales.length?Math.round(st.sales.reduce((n,s)=>n+s.total,0)/st.sales.length):0),'receipt',`${st.sales.length} orders · ${st.units} net units`)}</div><section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>Sales & profit over time</h2><div class="chart-legend"><span><i></i>Sales</span><span class="profit"><i></i>Profit</span></div></div><div class="panel-body">${lineChart(a,b)}</div></section><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Sales by category</h2></div><div class="panel-body">${bars(categories)}</div></section><section class="panel"><div class="panel-head"><h2>Payment methods</h2></div><div class="panel-body">${bars(payments)}</div></section></div><section class="panel"><div class="panel-head"><h2>Best-selling products</h2><span class="badge neutral">${ranks.length} products</span></div>${table(['Product','Units sold','Net revenue','Estimated profit'],ranks.map(r=>`<tr><td>${esc(r.name)}</td><td>${DB.roundQty(r.qty)}</td><td>${money(r.revenue)}</td><td>${money(r.profit)}</td></tr>`))}</section><p class="small muted" style="margin-top:16px">Refunds reduce results on the return date. Profit includes discounts and charges, excludes tax, and does not include shop expenses. Restocking updates purchase cost for future sales.</p>`;}
function categories(){return heading('Categories & brands','A tidy catalog makes selling easier.',btn('Add brand','add-brand','plus')+btn('Add category','add-category','plus','primary'))+['categories','brands'].map(store=>`<section style="margin-bottom:26px"><h2 style="margin-bottom:15px">${store==='categories'?'Categories':'Brands'}</h2><div class="list-grid">${data[store].filter(c=>!filters.q||c.name.toLowerCase().includes(filters.q.toLowerCase())).map(c=>`<div class="panel list-card"><span class="metric-icon">${icon('tag')}</span><h3 style="margin:17px 0 6px">${esc(c.name)}</h3><div class="muted small">${products().filter(p=>p[store==='categories'?'category':'brand']===c.name).length} products</div><div class="actions">${btn('Edit','edit-taxonomy','edit','compact',`data-store="${store}" data-id="${c.id}"`)}${iconBtn('Delete','delete-taxonomy','trash',`data-store="${store}" data-id="${c.id}"`)}</div></div>`).join('')}</div>${!data[store].length?empty(`No ${store} yet`,'Organize your products so they are easier to find.','','tag'):''}</section>`).join('');}
function settingsPage(){return heading('Store settings','Make StoreFlow feel like your shop.')+`<div class="settings-layout"><form id="settings-form"><section class="panel settings-panel"><h2>Shop details</h2><div class="form-grid">${field('Shop name','name',settings.name,'text','required maxlength="100"')}${field('Owner name','owner',settings.owner,'text','maxlength="100"')}${field('Phone','phone',settings.phone,'tel')}${field('Email','email',settings.email,'email')}${field('Address','address',settings.address,'text','maxlength="250"',true)}<div class="field span-2"><label for="shop-logo">Shop logo</label><input type="file" id="shop-logo" name="logo" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP. Images are compressed and saved on this device.</small>${settings.logo?`<img class="receipt-logo" src="${settings.logo}" alt="Shop logo">${checkField('Remove current logo','removeLogo',false)}`:''}</div></div></section><section class="panel settings-panel"><h2>Billing & inventory</h2><div class="form-grid">${field('Currency code','currency',settings.currency,'text','required minlength="3" maxlength="3"')}${field('Currency symbol','symbol',settings.symbol,'text','required maxlength="10"')}${field('Default tax (%)','tax',settings.tax,'number','min="0" max="100" step=".01" required')}${field('Default minimum stock','minStock',settings.minStock,'number','min="0" step=".001" required')}${field('Invoice prefix','prefix',settings.prefix,'text','required pattern="[A-Za-z0-9-]{1,12}" maxlength="12"')}${selectField('Theme','theme',['light','dark'],settings.theme)}${field('Receipt footer','footer',settings.footer,'text','maxlength="200"',true)}${checkField('Allow negative stock','negativeStock',settings.negativeStock)}${checkField('Scanner sound','sound',settings.sound)}${checkField('Scanner vibration','vibration',settings.vibration)}</div><p class="small muted" style="margin-top:16px">Changing currency changes the display label; it does not convert existing amounts. Tax applies after the bill discount, before additional charges.</p><div class="form-error" id="settings-error"></div><div class="dialog-actions"><button class="btn primary" type="submit">Save settings</button></div></section></form><section class="panel settings-panel"><h2>Backups & data</h2><div class="notice">This application stores your business data locally on this device/browser. Create regular backups to prevent data loss. Clearing browser storage, using private browsing, or changing your website address can make local records unavailable. There is no automatic device sync.</div><div class="data-actions">${btn('Export complete backup','backup','download','primary')}${btn('Import complete backup','restore','upload')}${btn('Keep storage on device','persist-storage','shield')}${btn('Products CSV','export-products','download')}${btn('Inventory CSV','export-products','download')}${btn('Sales CSV','export-sales','download')}${btn('Customers CSV','export-customers','download')}${btn('Stock movements CSV','export-movements','download')}${btn('CSV import template','csv-template','download')}</div><p class="small muted" style="margin-top:15px">A backup contains your images, sales, returns, customers, settings, stock ledger and saved bills. Restoring replaces the current workspace.</p></section><section class="panel settings-panel"><h2>App & offline access</h2><div class="actions">${btn('Install app','install','download')}${btn('How scanning works','scan-help','scan')}${btn(demo?'Clear demo data':'Explore demo shop',demo?'clear-demo':'demo-enter','grid')}</div><p class="small muted" style="margin-top:16px">After the first complete online load, your shop is available offline. Camera support depends on your browser and device. Backups transfer data between devices manually.</p><div id="storage-info" class="small muted"></div></section><section class="panel settings-panel"><h2>Reset options</h2><p class="muted small">Export a backup first. These actions cannot be undone without one.</p><div class="actions">${btn('Clear sales history','clear-sales','trash','danger')}${btn('Clear inventory','clear-inventory','trash','danger')}${btn('Reset application','reset','trash','danger')}</div></section></div>`;}
function morePage(){return heading('Your workspace','Everything you need to run your shop.')+`<div class="list-grid">${[['products','Products','box'],['stock-in','Receive stock','stock'],['sales','Sales & returns','receipt'],['customers','Customers','users'],['reports','Reports','chart'],['categories','Categories & brands','tag'],['movements','Stock movements','clock'],['settings','Settings & backups','settings']].map(([r,l,i])=>`<a class="panel list-card" href="#${r}"><span class="metric-icon">${icon(i)}</span><h3 style="margin-top:15px">${l}</h3></a>`).join('')}</div>`;}
async function reload(){data=await DB.snapshot();settings={...DB.defaults,...data.settings.find(s=>s.id==='store')};}
async function refresh(){await reload();render();channel?.postMessage({demo});}
function render(){shell();const views={dashboard,pos,products:()=>inventory(false),inventory:()=>inventory(true),'stock-in':stockIn,movements,sales,customers,reports,categories,settings:settingsPage,more:morePage};$('#main').innerHTML=(views[route]||dashboard)();if(route==='categories')$('#main').insertAdjacentHTML('afterbegin',`<div class="toolbar">${searchInput('Search categories or brands…',filters.q||'')}</div>`);if(route==='settings'&&navigator.storage?.estimate)navigator.storage.estimate().then(x=>{if($('#storage-info'))$('#storage-info').textContent=`Device storage used by this site: ${((x.usage||0)/1048576).toFixed(1)} MB`;});}
function navigate(r){if(location.hash==='#'+r){route=r;render();}else location.hash=r;}
function saveDraft(){clearTimeout(draftTimer);const copy=structuredClone(cart);return DB.put('settings',{id:'draft',cart:copy});}
function cartChanged(){saveDraft().catch(e=>toast(safeError(e),true));if($('#cart-panel'))$('#cart-panel').innerHTML=cartMarkup();if($('#scan-total'))$('#scan-total').textContent=settings.symbol+' '+(currentTotals().total/100).toLocaleString(undefined,{maximumFractionDigits:2});}
function addToCart(id,quantity=1){const p=product(id);if(!p||!p.active||p.deleted)throw new Error('This product is inactive or unavailable.');const l=cart.lines.find(l=>l.productId===id),qty=DB.roundQty((l?.qty||0)+quantity);if(!settings.negativeStock&&qty>p.stock)throw new Error(`Only ${p.stock} ${p.unit} of ${p.name} are available.`);if(qty<=0)throw new Error('Quantity must be greater than zero.');if(l)l.qty=qty;else cart.lines.push({productId:id,qty});cartChanged();}
function scan(mode,fast=false){openScanner(mode,{settings,fast,find:code=>data.products.find(p=>!p.deleted&&(p.barcode===code||p.sku===code)),total:()=>money(currentTotals().total).replace(/&amp;/g,'&'),found:async(p,m)=>{if(m==='sell')addToCart(p.id);else if(m==='stock')stockForm(p.id);else if(m==='add')productDetail(p.id);else productDetail(p.id);},add:code=>productForm(null,code,p=>{if(mode==='sell'){try{addToCart(p.id);}catch(e){toast(e.message,true);}}else if(mode==='stock')stockForm(p.id);}),checkout:checkoutForm}).catch(e=>toast(safeError(e),true));}
function productForm(id=null,barcode='',after=null){
 const p=id?product(id):{name:'',barcode,sku:'',category:'Uncategorized',brand:'',cost:0,price:0,stock:0,minStock:settings.minStock,unit:'pcs',expiry:'',description:'',image:'',active:true};if(!p)return;
 productAfterSave=after;
 showDialog(id?'Edit product':'Add product',`<form id="product-form" data-id="${id||''}"><div class="form-grid">${field('Product name','name',p.name,'text','required maxlength="150"',true)}${field('Barcode / QR value','barcode',p.barcode||'','text','maxlength="512"')}${field('SKU','sku',p.sku||'','text','maxlength="100"')}<div class="span-2 actions">${btn('Generate internal code','generate-code','barcode','compact')}<span class="small muted">Use your own barcode or create a CODE-128 label.</span></div>${field('Category','category',p.category,'text','list="category-options" required maxlength="100"')}${field('Brand','brand',p.brand,'text','list="brand-options" maxlength="100"')}<datalist id="category-options">${data.categories.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist><datalist id="brand-options">${data.brands.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist>${field(`Purchase price (${esc(settings.symbol)})`,'cost',p.cost/100,'number','min="0" max="1000000000" step=".01" required')}${field(`Selling price (${esc(settings.symbol)})`,'price',p.price/100,'number','min="0" max="1000000000" step=".01" required')}${field(id?'Current stock (use stock adjustment to change)':'Opening stock','stock',p.stock,'number',`${id?'readonly':''} min="${id?'-1000000000':'0'}" max="1000000000" step=".001" required`)}${field('Minimum stock alert','minStock',p.minStock,'number','min="0" step=".001" required')}${selectField('Unit','unit',['pcs','kg','g','L','ml','pack','box','dozen','m'],p.unit)}${field('Expiry date (optional)','expiry',p.expiry,'date')}<div class="field span-2"><label for="f-description">Description</label><textarea id="f-description" name="description" maxlength="1500">${esc(p.description)}</textarea></div><div class="field span-2"><label for="product-image">Product image</label><input id="product-image" type="file" name="image" accept="image/png,image/jpeg,image/webp">${p.image?`<div class="actions" style="margin-top:10px">${thumb(p,true)}${checkField('Remove image','removeImage',false)}</div>`:''}</div>${checkField('Active and available for sale','active',p.active)}</div><div class="form-error"></div><div class="dialog-actions">${id?btn('Delete product','delete-product','trash','danger',`data-id="${id}"`):''}${btn('Cancel','close')}<button class="btn primary" type="submit">${id?'Save changes':'Add product'}</button></div></form>`,true);
}
function productDetail(id){const p=product(id);if(!p)return;const recent=data.sales.filter(s=>s.lines.some(l=>l.productId===id)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),moves=data.movements.filter(m=>m.productId===id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);showDialog('Product details',`<div class="detail-top">${thumb(p,true)}<div><h2>${esc(p.name)}</h2><p class="muted small" style="margin:5px 0">${esc(p.category)}${p.brand?' · '+esc(p.brand):''}</p>${badge(p)}</div></div><div class="detail-grid"><div class="detail-stat"><span>Available stock</span><strong>${p.stock} ${esc(p.unit)}</strong></div><div class="detail-stat"><span>Selling price</span><strong>${money(p.price)}</strong></div><div class="detail-stat"><span>Purchase price</span><strong>${money(p.cost)}</strong></div><div class="detail-stat"><span>Profit per unit</span><strong>${money(p.price-p.cost)}</strong></div><div class="detail-stat"><span>Profit margin</span><strong>${profitPct(p)}%</strong></div><div class="detail-stat"><span>Opening stock</span><strong>${p.openingStock}</strong></div></div><p class="small"><strong>Barcode:</strong> ${esc(p.barcode||'—')}<br><strong>SKU:</strong> ${esc(p.sku||'—')}<br><strong>Expiry:</strong> ${esc(p.expiry||'Not set')}<br><strong>Added:</strong> ${fmtDate(p.created,true)}<br><strong>Updated:</strong> ${fmtDate(p.updated,true)}</p>${p.description?`<p class="muted small">${esc(p.description)}</p>`:''}<div class="actions">${btn('Edit','edit-product','edit','',`data-id="${id}"`)}${btn('Receive stock','stock-form','stock','primary',`data-id="${id}"`)}${btn('Print labels','labels','barcode','',`data-id="${id}"`)}</div><h3 style="margin:25px 0 12px">Recent sales</h3>${table(['Invoice','Date','Quantity'],recent.map(s=>`<tr><td><button class="table-link" data-action="receipt" data-id="${s.id}">${esc(s.invoice)}</button></td><td>${fmtDate(s.date)}</td><td>${s.lines.find(l=>l.productId===id).qty}</td></tr>`),'No sales for this product yet.')}<h3 style="margin:25px 0 12px">Recent stock movements</h3>${table(['Date','Type','Change','After'],moves.map(m=>`<tr><td>${fmtDate(m.date)}</td><td>${esc(m.type)}</td><td>${m.change>0?'+':''}${m.change}</td><td>${m.after}</td></tr>`))}`,true);}
function stockForm(id,adjust=false){const p=product(id);if(!p)return;showDialog(adjust?'Adjust stock':'Receive stock',`<div class="detail-top">${thumb(p)}<div><h3>${esc(p.name)}</h3><span class="muted small">Current stock: ${p.stock} ${esc(p.unit)} · Selling ${money(p.price)}</span></div></div><form id="stock-form" data-id="${id}" data-adjust="${adjust}"><div class="form-grid">${field(adjust?'Quantity change (negative to remove)':'Quantity received','qty','', 'number',`${adjust?'':'min="0.001"'} step=".001" required autofocus`)}${adjust?selectField('Reason','reason',['Stock correction','Damaged product','Lost product','Free sample','Manual increase','Manual decrease']):field(`Purchase price (${esc(settings.symbol)})`,'cost',p.cost/100,'number','min="0" step=".01" required')}${field(adjust?'Additional notes (optional)':'Delivery reference / notes (optional)','notes','','text','maxlength="300"',true)}</div><div class="form-error"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">${adjust?'Save adjustment':'Receive stock'}</button></div></form>`);}
function checkoutForm(){if(!cart.lines.length){toast('Add a product to the bill first.',true);return;}const t=DB.totals(cart,data.products);showDialog('Complete sale',`<p class="muted small" style="text-align:center">${esc(nameOf('customers',cart.customerId))} · ${cart.lines.length} product lines</p><div class="checkout-total">${money(t.total)}</div><form id="checkout-form"><div class="payment-options">${['Cash','Card','Bank Transfer','Other'].map((m,i)=>`<label><input type="radio" name="method" value="${m}" ${!i?'checked':''}>${m}</label>`).join('')}</div><div id="cash-fields">${field(`Amount received (${esc(settings.symbol)})`,'received',(t.total/100).toFixed(2),'number','min="0" step=".01" required inputmode="decimal"')}<div class="summary-row" style="margin-top:12px"><span class="muted">Change due</span><strong id="change-due">${money(0)}</strong></div></div><div class="notice small" style="margin-top:18px">Confirm once payment has been received. Card and bank payments are recorded here; they are processed outside this app.</div><div class="form-error"></div><div class="dialog-actions">${btn('Back to bill','close')}<button class="btn primary" type="submit">${icon('check')} Complete sale</button></div></form>`);}
function receiptMarkup(s){const sh=s.shop||settings;const sm=v=>`${esc(sh.symbol||settings.symbol)} ${(Number(v)/100).toLocaleString(undefined,{maximumFractionDigits:2})}`;return `<div class="receipt">${sh.logo&&/^data:image\/(jpeg|png|webp);base64,/.test(sh.logo)?`<img class="receipt-logo" src="${sh.logo}" alt="">`:''}<h2>${esc(sh.name)}</h2><div class="center">${esc(sh.address)}<br>${esc(sh.phone)}</div><div class="receipt-rule"></div><div><strong>${esc(s.invoice)}</strong><br>${fmtDate(s.date,true)}<br>Customer: ${esc(s.customerName)}</div><table><thead><tr><th>Item / price</th><th class="right">Qty</th><th class="right">Amount</th></tr></thead><tbody>${s.lines.map(l=>`<tr><td>${esc(l.name)}<br><span class="muted">${sm(l.price)}</span></td><td class="right">${l.qty}</td><td class="right">${sm(l.gross)}</td></tr>`).join('')}</tbody></table><div class="summary-row"><span>Subtotal</span><span>${sm(s.subtotal)}</span></div><div class="summary-row"><span>Discount</span><span>− ${sm(s.discount)}</span></div><div class="summary-row"><span>Tax</span><span>${sm(s.tax)}</span></div><div class="summary-row"><span>Charges</span><span>${sm(s.charges)}</span></div><div class="summary-row total"><span>Total</span><span>${sm(s.total)}</span></div><div class="summary-row"><span>Payment</span><span>${esc(s.payment.method)}</span></div><div class="summary-row"><span>Received</span><span>${sm(s.payment.received)}</span></div><div class="summary-row"><span>Change</span><span>${sm(s.payment.change)}</span></div>${s.refunded?`<div class="summary-row"><span>Refunded</span><span>${sm(s.refunded)}</span></div><div class="summary-row"><span>Net paid</span><span>${sm(s.total-s.refunded)}</span></div>`:''}<div class="receipt-rule"></div><p class="center">${esc(sh.footer)}</p><p class="center small">Powered by StoreFlow POS</p></div>`;}
function receipt(id){
 const s=data.sales.find(x=>x.id===id);if(!s)return;
 const returns=data.returns.filter(r=>r.saleId===id);
 const returnHTML=returns.length?'<h3 style="margin-top:20px">Returns</h3>'+returns.map(r=>`<div class="notice small">${fmtDate(r.date,true)} · ${money(r.amount)}<br>${esc(r.reason)}</div>`).join(''):'';
 const buttons=`<div class="actions" style="justify-content:center;margin-top:23px">${btn('Print / PDF','print-receipt','print','primary',`data-id="${id}"`)}${btn('58mm','print-58','print','',`data-id="${id}"`)}${btn('80mm','print-80','print','',`data-id="${id}"`)}</div>`;
 const profit=`<div class="summary-row small" style="margin-top:15px"><span class="muted">Estimated profit before returns</span><strong>${money(s.profit)}</strong></div>`;
 const footer=`<div class="dialog-actions">${btn('Return products','return-form','return','',`data-id="${id}"`)}${btn('New sale','new-sale','plus','primary')}</div>`;
 showDialog('Sale receipt',receiptMarkup(s)+buttons+profit+returnHTML+footer);
}
function printContent(html,width){$('#print-area').innerHTML=html;document.body.classList.remove('thermal-58','thermal-80');if(width)document.body.classList.add('thermal-'+width);let style=$('#print-page-style');if(!style){style=document.createElement('style');style.id='print-page-style';document.head.append(style);}style.textContent=width?`@page{size:${width}mm auto;margin:4mm}`:'@page{size:auto;margin:10mm}';window.print();}
function returnForm(id){const s=data.sales.find(s=>s.id===id);const lines=s.lines.filter(l=>DB.roundQty(l.qty-l.returned)>0);if(!lines.length){toast('All products on this invoice have been returned.');return;}showDialog('Return products',`<p class="muted small">${esc(s.invoice)} · Refunds include the proportional discount, tax and charges.</p><form id="return-form" data-id="${id}">${lines.map(l=>`<div class="return-line"><label for="return-${l.productId}">${esc(l.name)}<small>${DB.roundQty(l.qty-l.returned)} available to return · ${money(l.price)} each</small></label><input id="return-${l.productId}" type="number" name="${l.productId}" min="0" max="${DB.roundQty(l.qty-l.returned)}" step=".001" value="0" aria-label="Return quantity for ${esc(l.name)}"></div>`).join('')}<div style="margin-top:19px">${field('Return reason','reason','','text','required maxlength="300"')}</div><div class="summary-row total"><span>Refund</span><strong id="refund-total">${money(0)}</strong></div><div class="notice">Returned items go back into stock. Pay the customer the displayed refund outside this app. For damaged goods, record a stock adjustment afterwards.</div><div class="form-error"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">Confirm return & refund</button></div></form>`);}
