function heldBills(){showDialog('Held bills',data.heldBills.length?data.heldBills.map(h=>{let total;try{total=DB.totals(h,data.products).total;}catch{total=h.total||0;}return `<div class="return-line"><div><strong>${esc(nameOf('customers',h.customerId))}</strong><small>${fmtDate(h.date,true)} · ${h.lines.length} product lines · ${money(total)}</small></div><div class="actions">${btn('Resume','resume-bill','cart','',`data-id="${h.id}"`)}${iconBtn('Delete held bill','delete-held','trash',`data-id="${h.id}"`)}</div></div>`;}).join(''):empty('No held bills','Park an unfinished bill from the cashier and come back to it later.','','hold'));}
