function onboarding(step=1){if(step===1)showDialog('Welcome to StoreFlow',`<div class="welcome"><div class="welcome-mark">${icon('store')}</div><h1>Your shop.<br>A little more in flow.</h1><p>Manage your products, scan items and finish a sale — all from this device.</p><div class="onboarding-steps"><span class="active"></span><span></span><span></span></div><form id="onboarding-form"><div class="form-grid">${field('Shop name','name',settings.name==='My store'?'':settings.name,'text','required placeholder="e.g. The Corner Store" maxlength="100"',true)}${selectField('Currency','currency',[['PKR','PKR — Pakistani rupee'],['USD','USD — US dollar'],['GBP','GBP — British pound'],['EUR','EUR — Euro'],['AED','AED — UAE dirham'],['INR','INR — Indian rupee']],settings.currency)}${field('Your name (optional)','owner',settings.owner,'text','maxlength="100"')}</div><div class="form-error"></div><div class="dialog-actions">${btn('Explore demo','demo-enter','grid')}<button class="btn primary" type="submit">Set up my shop ${icon('arrow')}</button></div></form></div>`);
 else if(step===2)showDialog('Add your first product',`<div class="welcome"><div class="welcome-mark">${icon('box')}</div><h1>Start with one product.</h1><p>Add a name, price and opening stock. If the product has a barcode, scan it and we’ll fill it in.</p><div class="onboarding-steps"><span class="active"></span><span class="active"></span><span></span></div><div class="feature-list"><div>${icon('check')} Your products stay saved after closing the browser.</div><div>${icon('scan')} Scan a barcode without taking a photo.</div><div>${icon('shield')} Regular backups keep a second copy safe.</div></div><div class="dialog-actions">${btn('Skip for now','onboard-next')}${btn('Add first product','onboard-product','plus','primary')}</div></div>`);
 else scanHelp(true);
}
function scanHelp(onboard=false){showDialog('Ready to scan & sell',`<div class="welcome"><div class="welcome-mark">${icon('scan')}</div><h2>A checkout in five simple steps</h2><div class="feature-list"><div><strong>1</strong> Open Point of sale and tap Scan.</div><div><strong>2</strong> Allow your phone’s camera and point at a barcode.</div><div><strong>3</strong> Products enter the bill automatically. Move a code out of view before scanning it again.</div><div><strong>4</strong> Close the scanner, check the bill and tap Checkout.</div><div><strong>5</strong> Record payment. Your receipt and updated stock are saved together.</div></div><p>Use your published HTTPS website. Camera availability varies by device. You can also type a barcode or use a USB scanner in product search.</p><div class="dialog-actions">${btn(onboard?'Start selling':'Open cashier','new-sale','cart','primary')}</div></div>`);}
async function switchDemo(on){await saveDraft();closeDialog();closeScanner();demo=on;localStorage.setItem('storeflow-demo',on?'1':'0');await DB.openDB(demo);if(on)await seedDemo();await reload();cart=data.settings.find(s=>s.id==='draft')?.cart||DB.newCart(settings.tax);filters={};route='dashboard';location.hash='dashboard';render();if(!on&&!settings.onboarded)onboarding();}
function chooseFile(accept,callback){const i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=()=>{if(i.files[0])callback(i.files[0]).catch(e=>toast(safeError(e),true));};i.click();}
function exportCSV(kind){let rows;
 if(kind==='products')rows=[['Name','Barcode','SKU','Category','Brand','Purchase Price','Selling Price','Stock','Minimum Stock','Unit','Expiry','Active'],...products().map(p=>[p.name,p.barcode||'',p.sku||'',p.category,p.brand,p.cost/100,p.price/100,p.stock,p.minStock,p.unit,p.expiry,p.active])];
 else if(kind==='sales')rows=[['Invoice','Date','Customer','Items','Subtotal','Discount','Tax','Charges','Original Total','Refunded','Net Total','Payment','Original Profit'],...data.sales.map(s=>[s.invoice,s.date,s.customerName,s.lines.reduce((n,l)=>n+l.qty,0),s.subtotal/100,s.discount/100,s.tax/100,s.charges/100,s.total/100,s.refunded/100,(s.total-s.refunded)/100,s.payment.method,s.profit/100])];
 else if(kind==='customers')rows=[['Name','Phone','Email','Address','Notes','Orders','Total Spending'],...data.customers.map(c=>{const ss=data.sales.filter(s=>s.customerId===c.id);return [c.name,c.phone,c.email,c.address,c.notes,ss.length,ss.reduce((n,s)=>n+s.total-s.refunded,0)/100];})];
 else rows=[['Date','Product','Type','Before','Change','After','Reference','Reason'],...data.movements.map(m=>[m.date,m.product,m.type,m.before,m.change,m.after,m.reference,m.reason])];
 download(`storeflow-${kind}-${DB.today()}.csv`,csvExport(rows),'text/csv;charset=utf-8');toast('CSV exported');
}
