function csvImportDialog(){showDialog('Import products from CSV',`<p class="muted">Add new products in bulk. Existing products are never overwritten.</p><div class="notice">Required columns: Name, Purchase Price, Selling Price, Stock. Optional: Barcode, SKU, Category, Brand, Minimum Stock, Unit. Save barcodes as text to preserve leading zeroes.</div><div class="actions">${btn('Download template','csv-template','download')}${btn('Choose CSV file','csv-choose','upload','primary')}</div>`);}
