document.addEventListener('submit',async e=>{
 const form=e.target;if(form.id==='manual-scan')return;e.preventDefault();if(busy)return;busy=true;const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;const err=form.querySelector('.form-error');if(err)err.textContent='';
 try{await submitForm(form);}catch(error){const message=safeError(error);if(err&&err.isConnected)err.textContent=message;else toast(message,true);}finally{busy=false;if(submit)submit.disabled=false;}
});
let debounce;
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='page-search'){clearTimeout(debounce);const value=el.value,start=el.selectionStart;debounce=setTimeout(()=>{filters.q=value;limit=40;render();const input=$('#page-search');input?.focus();if(input)input.setSelectionRange(start,start);},150);}
 if(el.id==='global-query'){clearTimeout(debounce);debounce=setTimeout(()=>globalResults(el.value),120);}
 if(el.name==='received'&&el.closest('#checkout-form')){$('#change-due').textContent=`${settings.symbol} ${Math.max(0,(Number(el.value)*100-currentTotals().total)/100).toFixed(2)}`;}
 if(el.closest('#return-form')&&el.type==='number'){
  const form=el.closest('form'),s=data.sales.find(s=>s.id===form.dataset.id);let total=0;for(const l of s.lines){const qty=Math.min(l.qty-l.returned,Math.max(0,Number(form.elements[l.productId]?.value)||0));total+=Math.round(l.total*(l.returned+qty)/l.qty)-Math.round(l.total*l.returned/l.qty);}$('#refund-total').innerHTML=money(total);
 }
});
document.addEventListener('change',async e=>{
 try{
 const el=e.target,mappings={'category-filter':'category','brand-filter':'brand','status-filter':'status','sort-filter':'sort','payment-filter':'payment','sales-from':'from','sales-to':'to','movement-filter':'type'};
 if(mappings[el.id]){filters[mappings[el.id]]=el.value;limit=40;render();}
 if(el.id==='range'){range=el.value;if(range==='custom'&&!customFrom){customFrom=DB.today();customTo=DB.today();}render();}
 if(el.id==='date-from'||el.id==='date-to'){if(el.id==='date-from')customFrom=el.value;else customTo=el.value;if(customFrom&&customTo&&customFrom<=customTo)render();else toast('Choose a valid start and end date.',true);}
 if(el.classList.contains('cart-qty')){const l=cart.lines.find(l=>l.productId===el.dataset.id),p=product(el.dataset.id),q=DB.roundQty(DB.number(el.value,'Quantity',.001));if(!settings.negativeStock&&q>p.stock)throw new Error(`Only ${p.stock} ${p.unit} are available.`);l.qty=q;cartChanged();}
 if(el.id.startsWith('cart-')){
  if(el.id==='cart-customer')cart.customerId=el.value;
  if(el.id==='cart-discountType'){cart.discountType=el.value;cart.discount=0;}
  if(el.id==='cart-discount')cart.discount=cart.discountType==='percent'?DB.number(el.value,'Discount',0,100):DB.cents(el.value);
  if(el.id==='cart-tax')cart.tax=DB.number(el.value,'Tax',0,100);
  if(el.id==='cart-charges')cart.charges=DB.cents(el.value);
  cartChanged();if(el.closest('details'))$('#cart-panel details').open=true;
 }
 if(el.name==='method'&&el.closest('#checkout-form')){$('#cash-fields').hidden=el.value!=='Cash';$('#f-received').required=el.value==='Cash';}
 }catch(err){toast(safeError(err),true);if($('#cart-panel'))$('#cart-panel').innerHTML=cartMarkup();}
});
async function action(a,id,el){
 if(a==='close')closeDialog();
 else if(a==='collapse'){localStorage.setItem('storeflow-collapsed',document.body.classList.contains('collapsed')?'0':'1');shell();}
 else if(a==='theme'){const theme=document.body.classList.contains('dark')?'light':'dark';localStorage.setItem('storeflow-theme',theme);shell();}
 else if(a==='global-search')globalSearch();
 else if(a==='new-sale'){closeDialog();navigate('pos');}
 else if(a==='add-product')productForm();
 else if(a==='edit-product')productForm(id);
 else if(a==='product-detail')productDetail(id);
 else if(a==='stock-in')navigate('stock-in');
 else if(a==='stock-form')stockForm(id);
 else if(a==='adjust-stock')stockForm(id,true);
 else if(a==='scan-sell'||a==='fast-sell'){closeDialog();if(route!=='pos')navigate('pos');scan('sell',a==='fast-sell');}
 else if(a==='scan-stock')scan('stock');
 else if(a==='scan-add-mode')scan('add');
 else if(a==='scan-lookup')scan('lookup');
 else if(a==='scan-help')scanHelp();
 else if(a==='onboard-next')onboarding(3);
 else if(a==='onboard-product')productForm(null,'',()=>onboarding(3));
 else if(a==='cart-add'){addToCart(id);toast('Product added to bill');}
 else if(a==='cart-plus')addToCart(id);
 else if(a==='cart-minus'){const l=cart.lines.find(l=>l.productId===id);if(l.qty<=1)cart.lines=cart.lines.filter(l=>l.productId!==id);else l.qty=DB.roundQty(l.qty-1);cartChanged();}
 else if(a==='cart-remove'){cart.lines=cart.lines.filter(l=>l.productId!==id);cartChanged();}
 else if(a==='cart-clear'){if(cart.lines.length)confirmAction('Clear current bill?','This removes the current bill. Your inventory will not change.',async()=>{cart=DB.newCart(settings.tax);await saveDraft();render();},'CLEAR');}
 else if(a==='pos-category'){filters.category=el.dataset.category;limit=40;render();}
 else if(a==='checkout')checkoutForm();
 else if(a==='receipt')receipt(id);
 else if(a==='return-form')returnForm(id);
 else if(a==='print-receipt'||a==='print-58'||a==='print-80'){const s=data.sales.find(s=>s.id===id);printContent(receiptMarkup(s),a==='print-receipt'?null:a.slice(-2));}
 else if(a==='hold-bill'){
  if(!cart.lines.length)throw new Error('Add a product before holding this bill.');await DB.put('heldBills',{...structuredClone(cart),date:new Date().toISOString(),total:currentTotals().total});cart=DB.newCart(settings.tax);await saveDraft();await refresh();toast('Bill held');
 }else if(a==='held-bills')heldBills();
 else if(a==='resume-bill'){
  if(cart.lines.length)throw new Error('Hold or clear the current bill before resuming another.');const h=data.heldBills.find(h=>h.id===id);if(!h)throw new Error('This held bill is no longer available.');cart={...structuredClone(h),heldId:h.id};await DB.atomic(['heldBills','settings'],async s=>{await DB.req(s.settings.put({id:'draft',cart:structuredClone(cart)}));await DB.req(s.heldBills.delete(id));});closeDialog();await refresh();navigate('pos');toast('Bill restored. Prices and availability use the current catalog.');
 }else if(a==='delete-held')confirmAction('Delete held bill?','The saved bill will be removed. Stock is unchanged.',async()=>{await DB.remove('heldBills',id);await refresh();heldBills();});
 else if(a==='low-stock'){filters={status:'Low stock'};route='inventory';location.hash='inventory';render();}
 else if(a==='more-records'){limit+=40;render();}
 else if(a==='add-customer')customerForm();
 else if(a==='edit-customer')customerForm(id);
 else if(a==='add-category')taxonomyForm('categories');
 else if(a==='add-brand')taxonomyForm('brands');
 else if(a==='edit-taxonomy')taxonomyForm(el.dataset.store,id);
 else if(a==='delete-taxonomy'){
  const store=el.dataset.store,c=data[store].find(c=>c.id===id);confirmAction(`Delete ${store==='categories'?'category':'brand'}?`,`${esc(c.name)} will be removed. Products will ${store==='categories'?'move to Uncategorized':'have no brand'}.`,async()=>{await DB.atomic([store,'products'],async s=>{await DB.req(s[store].delete(id));for(const p of await DB.req(s.products.getAll())){const key=store==='categories'?'category':'brand';if(p[key]===c.name){p[key]=store==='categories'?'Uncategorized':'';await DB.req(s.products.put(p));}}});await refresh();toast('Removed');});
 }else if(a==='delete-customer')confirmAction('Delete customer?','The customer will be removed. Existing invoices keep their original customer details.',async()=>{await DB.remove('customers',id);await refresh();toast('Customer deleted');});
 else if(a==='delete-product')confirmAction('Delete product?',`This product will leave your catalog. Historical sales and stock records are retained.`,async()=>{await DB.atomic(['products'],async s=>{const p=await DB.req(s.products.get(id));p.deleted=true;p.active=false;p.image='';p.updated=new Date().toISOString();await DB.req(s.products.put(p));});cart.lines=cart.lines.filter(l=>l.productId!==id);await saveDraft();await refresh();toast('Product deleted');});
 else if(a==='generate-code'){const code='SF-'+DB.uid().replaceAll('-','').slice(0,12).toUpperCase();$('#f-barcode').value=code;$('#f-sku').value=code;}
 else if(a==='backup')await backup();
 else if(a==='restore')chooseFile('.json,application/json',async file=>{if(file.size>100*1024*1024)throw new Error('Backup exceeds the 100 MB import limit.');let b;try{b=JSON.parse(await file.text());}catch{throw new Error('The backup is not valid JSON.');}pendingBackup=validateBackup(b);confirmAction('Restore complete backup?',`Backup created ${fmtDate(b.exportedAt,true)} · version ${esc(b.appVersion)}.<br>${b.data.products.length} products, ${b.data.sales.length} sales, ${b.data.customers.length} customers.<br><strong>All data in this ${demo?'demo':'real'} workspace will be replaced.</strong> Export your current backup first.`,async()=>{await restoreBackup(pendingBackup);pendingBackup=null;await reload();cart=data.settings.find(s=>s.id==='draft')?.cart||DB.newCart(settings.tax);render();channel?.postMessage({demo});toast('Backup restored');},'RESTORE');});
 else if(a.startsWith('export-'))exportCSV(a.slice(7));
 else if(a==='csv-template')download('storeflow-products-template.csv',csvExport([['Name','Barcode','SKU','Category','Brand','Purchase Price','Selling Price','Stock','Minimum Stock','Unit'],['Example product','SF-0001','SKU-0001','Groceries','Example',100,130,20,5,'pcs']]),'text/csv;charset=utf-8');
 else if(a==='csv-import')csvImportDialog();
 else if(a==='csv-choose')chooseFile('.csv,text/csv',async file=>{if(file.size>10*1024*1024)throw new Error('Choose a CSV smaller than 10 MB.');importRows=previewCSV(await file.text(),data.products);csvPreview(importRows);});
 else if(a==='csv-confirm'){if(!importRows.length)throw new Error('Choose a CSV file first.');await importCSV(importRows);const count=importRows.length;importRows=[];closeDialog();await refresh();toast(`${count} products imported`);}
 else if(a==='labels')await labelsDialog(id);
 else if(a==='print-labels')printContent($('#labels-ready').outerHTML);
 else if(a==='demo-enter')await switchDemo(true);
 else if(a==='demo-exit')await switchDemo(false);
 else if(a==='clear-demo')confirmAction('Clear demo data?','This clears only the demo workspace. Your real shop is not changed.',async()=>{await DB.atomic(DB.STORES,async s=>{for(const n of DB.STORES)await DB.req(s[n].clear());});cart=DB.newCart();await switchDemo(false);},'CLEAR');
 else if(a==='persist-storage'){if(navigator.storage?.persist){const ok=await navigator.storage.persist();toast(ok?'Persistent storage enabled. Keep regular backups too.':'Your browser decides storage persistence. Installing the app may help.');}else toast('This browser does not offer a storage persistence setting.');}
 else if(a==='install'){if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null;}else showDialog('Install StoreFlow',`<div class="feature-list"><div>${icon('download')}<span><strong>Android / Chrome:</strong> Open the browser menu and choose Install app or Add to Home screen.</span></div><div>${icon('download')}<span><strong>iPhone / Safari:</strong> Tap Share, then Add to Home Screen.</span></div><div>${icon('info')}<span>If already installed, open StoreFlow from your home screen. Installation is available after the site is served over HTTPS.</span></div></div>`);}
 else if(a==='clear-sales')confirmAction('Clear sales history?',`Sales, returns and their stock ledger entries will be removed. Current stock quantities remain unchanged, with a new ledger baseline. Customer spending reports will reset. Export a backup first.`,async()=>{await DB.atomic(['sales','returns','movements','products'],async s=>{await DB.req(s.sales.clear());await DB.req(s.returns.clear());await DB.req(s.movements.clear());for(const p of await DB.req(s.products.getAll()))await DB.req(s.movements.add(DB.movement(p,0,p.stock,'Adjustment','Baseline after clearing sales history')));});await refresh();toast('Sales history cleared');},'CLEAR');
 else if(a==='clear-inventory')confirmAction('Clear inventory?',`All products, categories and brands will leave the catalog. Referenced products remain archived for invoices and returns. Current and held bills will be cleared. Export a backup first.`,async()=>{await DB.atomic(['products','categories','brands','heldBills','settings','movements'],async s=>{for(const p of await DB.req(s.products.getAll())){if(p.stock)await DB.req(s.movements.add(DB.movement(p,p.stock,-p.stock,'Adjustment','Inventory cleared')));p.stock=0;p.deleted=true;p.active=false;p.image='';await DB.req(s.products.put(p));}for(const n of ['categories','brands','heldBills'])await DB.req(s[n].clear());await DB.req(s.settings.delete('draft'));});cart=DB.newCart(settings.tax);await refresh();toast('Inventory cleared');},'CLEAR');
 else if(a==='reset')confirmAction('Reset application?',`Every record in this ${demo?'demo':'real'} workspace will be deleted. This includes products, sales, settings and customers. Export a backup before continuing.`,async()=>{await DB.atomic(DB.STORES,async s=>{for(const n of DB.STORES)await DB.req(s[n].clear());});cart=DB.newCart();await reload();render();onboarding();},'RESET');
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;if(['scan-close','scan-ignore','scan-add','scan-checkout','torch'].includes(a))return;e.preventDefault();if(busy)return;busy=true;try{await action(a,el.dataset.id,el);}catch(err){toast(safeError(err),true);}finally{busy=false;}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1).split('?')[0]||'dashboard';if(next!==route){route=next;filters={};limit=40;}render();window.scrollTo(0,0);});
window.addEventListener('online',shell);window.addEventListener('offline',shell);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('pagehide',()=>closeScanner());
channel&&(channel.onmessage=async e=>{if(e.data.demo===demo){await reload();render();}});
document.addEventListener('keydown',e=>{
 const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName),modal=$('#dialog').open||$('#scanner').open;
 if(e.key==='Escape'&&$('#scanner').open&&!$('#dialog').open)closeScanner();
 if(e.key==='/'&&!typing&&!modal){e.preventDefault();globalSearch();}
 if(!modal&&route==='pos'){
  if(e.key==='F2'){e.preventDefault();$('#page-search')?.focus();}
  if(e.key==='F4'){e.preventDefault();scan('sell');}
  if(e.key==='F8'){e.preventDefault();checkoutForm();}
  if(e.key==='Enter'&&e.target.id==='page-search'){const code=e.target.value.trim(),p=products().find(p=>p.barcode===code||p.sku===code);if(p){e.preventDefault();clearTimeout(debounce);try{addToCart(p.id);filters.q='';render();$('#page-search')?.focus();toast('Product added to bill');}catch(err){toast(err.message,true);}}}
 }
});
function registerTools(){
 if(!document.modelContext?.registerTool)return;
 const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});
 const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};
 register({name:'search_store_products',description:'Read local product availability and prices matching a name, barcode or SKU.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw new Error('Provide a query up to 200 characters.');return products().filter(p=>searchProduct(p,query)).slice(0,30).map(p=>({id:p.id,name:p.name,barcode:p.barcode,stock:p.stock,price:p.price/100,currency:settings.currency}));}});
 register({name:'stage_products_in_bill',description:'Add products to the current bill and open the cashier. Does not complete payment or deduct stock.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:50,items:{type:'object',properties:{productId:{type:'string'},quantity:{type:'number',exclusiveMinimum:0}},required:['productId','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async({items})=>{if(!Array.isArray(items)||!items.length||items.length>50)throw new Error('Provide 1 to 50 items.');const before=structuredClone(cart);try{for(const i of items){if(typeof i.productId!=='string')throw new Error('Invalid product ID.');DB.number(i.quantity,'Quantity',.001);const p=product(i.productId),old=cart.lines.find(l=>l.productId===i.productId),q=DB.roundQty((old?.qty||0)+i.quantity);if(!p||p.deleted||!p.active||(!settings.negativeStock&&p.stock<q))throw new Error('Product unavailable or insufficient stock.');if(old)old.qty=q;else cart.lines.push({productId:p.id,qty:q});}await saveDraft();navigate('pos');return {lines:cart.lines.length,total:currentTotals().total/100,currency:settings.currency};}catch(e){cart=before;throw e;}}});
}
async function start(){
 try{if(!window.indexedDB)throw new Error('IndexedDB unavailable');await DB.openDB(demo);if(demo)await seedDemo();await reload();if(!data.settings.some(s=>s.id==='store')){await DB.put('settings',{...DB.defaults});await reload();}cart=data.settings.find(s=>s.id==='draft')?.cart||DB.newCart(settings.tax);route=location.hash.slice(1).split('?')[0]||'dashboard';render();if(!settings.onboarded&&!demo)onboarding();registerTools();if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(()=>toast('Offline setup could not finish. Reconnect and reload once.',true));}
 catch(error){console.error(error);$('#main').innerHTML=empty('Your browser could not open the local database','Use a regular browser window, allow site storage, and reload. Your existing data has not been intentionally changed.',btn('Reload','reload','refresh'),'alert');document.querySelector('[data-action="reload"]').onclick=()=>location.reload();}
}
start();
